def has_path(coll, path):
    """Returns True if all keys in path exist in the nested collection.

    Returns False if any key in the path doesn't exist.
    An empty path returns True (vacuously true).
    """
    for key in path:
        try:
            coll = coll[key]
        except (KeyError, IndexError, TypeError):
            return False
    return True

